#include <linux/slab.h>
#include <linux/netlink.h>

int create_hardware_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = {0};
    int ret = 0;

    // Initialize default values
    params.regulatory_strict = false;
    params.no_p2p = false;
    params.channels = 0;
    params.name = NULL;

    // Extract attributes from the netlink message
    if (info->attrs[ATTR_RADIO_REGULATORY_STRICT]) {
        params.regulatory_strict = true;
    }

    if (info->attrs[ATTR_RADIO_NO_P2P]) {
        params.no_p2p = true;
    }

    if (info->attrs[ATTR_RADIO_CHANNELS]) {
        params.channels = nla_get_u32(info->attrs[ATTR_RADIO_CHANNELS]);
        if (params.channels <= 0) {
            return -EINVAL;
        }
    }

    if (info->attrs[ATTR_RADIO_NAME]) {
        size_t name_len = strlen(nla_data(info->attrs[ATTR_RADIO_NAME])) + 1;
        params.name = kmalloc(name_len, GFP_KERNEL);
        if (!params.name) {
            return -ENOMEM;
        }
        strncpy(params.name, nla_data(info->attrs[ATTR_RADIO_NAME]), name_len - 1);
        params.name[name_len - 1] = '\0';
    }

    if (info->attrs[ATTR_RADIO_REGDOMAIN_IDX]) {
        int regdomain_idx = nla_get_u32(info->attrs[ATTR_RADIO_REGDOMAIN_IDX]);
        if (regdomain_idx < 0 || regdomain_idx >= MAX_REGDOMAINS) {
            ret = -EINVAL;
            goto error;
        }
        params.regdomain_idx = regdomain_idx;
    }

    // Create the radio
    ret = mac80211_hwsim_new_radio(&params);

    error:
    if (params.name) {
        kfree(params.name);
    }
    return ret;
}
